-- DDL migration 005 — figure registry v1.2 (multi-figure per chapter)
-- v5.4 expansion: each chapter now has 4 figures (1 v5.3 engraved + 1 legacy + 2 cross-ref)
-- Refs: trios#380, trios#265, trios#619, PR #627
-- Anchor: phi^2 + phi^-2 = 3 · DOI 10.5281/zenodo.19227877

BEGIN;

CREATE TABLE IF NOT EXISTS ssot.chapter_figures_v2 (
  chapter_slug TEXT NOT NULL,
  figure_index SMALLINT NOT NULL,
  figure_filename TEXT NOT NULL,
  figure_role TEXT NOT NULL CHECK (figure_role IN ('chapter','legacy','cross-ref')),
  figure_source_url TEXT NOT NULL,
  alt_text TEXT NOT NULL,
  license TEXT DEFAULT 'CC-BY-4.0',
  inserted_at TIMESTAMPTZ DEFAULT NOW(),
  PRIMARY KEY (chapter_slug, figure_index)
);

TRUNCATE ssot.chapter_figures_v2;


-- Verification:
-- SELECT chapter_slug, COUNT(*) FROM ssot.chapter_figures_v2 GROUP BY chapter_slug ORDER BY chapter_slug;
-- Expected: 34 rows, each with count=4

COMMIT;
